183		defer s.mu.Unlock()
184		v, ok := s.volumes[id]
185		if !ok {
186			writeError(w, http.StatusNotFound, "volume_not_found")
187			return
188		}
189		if v.binding != "" {
190			writeError(w, http.StatusConflict, "volume_in_use")
191			return
192		}
193		s.pools[v.poolID].volumeBytes -= v.sizeBytes
194		s.pools[v.poolID].tenantUsed[v.tenant] -= v.sizeBytes
195		delete(s.volumes, id)
196		s.appendAudit(auditVolumeDeleted, volumePath+"/"+id, v.poolID, -v.sizeBytes)
197		w.WriteHeader(http.StatusNoContent)
