200	func (s *store) putBinding(w http.ResponseWriter, r *http.Request, volumeID string) {
201		var in bindingInput
202		if !decodeRequest(r, &in) {
203			writeError(w, http.StatusBadRequest, "invalid_request")
204			return
205		}
206		if !validID(volumeID) || !validID(in.NodeID) || in.ExpectedGeneration == nil || *in.ExpectedGeneration < 0 {
207			writeError(w, http.StatusBadRequest, "invalid_request")
208			return
209		}
210		expected := *in.ExpectedGeneration
211	
212		s.mu.Lock()
213		defer s.mu.Unlock()
214		v, ok := s.volumes[volumeID]
215		if !ok {
216			writeError(w, http.StatusNotFound, "volume_not_found")
217			return
218		}
219		if v.generation != expected {
220			writeError(w, http.StatusConflict, "stale_generation")
221			return
222		}
223		switch {
224		case v.binding == "":
225			v.binding = in.NodeID
226			v.generation++
227			s.appendAudit(auditVolumeBound, volumePath+"/"+volumeID+"/binding", v.poolID, 0)
228		case v.binding != in.NodeID:
229			writeError(w, http.StatusConflict, "volume_already_bound")
230			return
231		}
232		// A same-node, same-generation PUT is an idempotent no-op that returns
233		// the current representation without bumping the generation.
234		writeJSON(w, http.StatusOK, v.view())
235	}
236	
237	func (s *store) deleteBinding(w http.ResponseWriter, r *http.Request, volumeID string) {
238		// expectedGeneration is the single accepted query parameter; it must be
239		// present exactly once. Parse the raw string manually so malformed or
240		// duplicated parameters cannot be silently discarded.
241		gen, ok := parseGenerationQuery(r.URL.RawQuery)
242		if !ok || !validID(volumeID) {
243			writeError(w, http.StatusBadRequest, "invalid_request")
244			return
245		}
246	
247		s.mu.Lock()
248		defer s.mu.Unlock()
249		v, exists := s.volumes[volumeID]
250		if !exists {
251			writeError(w, http.StatusNotFound, "volume_not_found")
252			return
253		}
254		if v.generation != gen {
255			writeError(w, http.StatusConflict, "stale_generation")
256			return
257		}
258		wasBound := v.binding != ""
259		v.binding = ""
260		if wasBound {
261			v.generation++
262			// Unbinding an already-unbound volume is a successful no-op: no
263			// generation bump and no audit event.
264			s.appendAudit(auditVolumeUnbound, volumePath+"/"+volumeID+"/binding", v.poolID, 0)
265		}
266		w.WriteHeader(http.StatusNoContent)
267	}
268	
269	// parseGenerationQuery accepts exactly one "expectedGeneration=<non-neg-int>"
270	// pair. Missing, empty, duplicated or extra parameters yield ok=false.
271	func parseGenerationQuery(raw string) (int64, bool) {
272		if raw == "" {
273			return 0, false
274		}
275		var gen int64
276		found := false
277		for _, pair := range strings.Split(raw, "&") {
278			key, value, ok := strings.Cut(pair, "=")
279			if !ok {
280				return 0, false
281			}
282			decodedKey, err := url.QueryUnescape(key)
283			if err != nil {
284				return 0, false
285			}
286			if decodedKey != "expectedGeneration" {
287				return 0, false
288			}
289			if found {
290				return 0, false
291			}
292			decodedValue, err := url.QueryUnescape(value)
293			if err != nil {
294				return 0, false
295			}
296			parsed, err := strconv.ParseInt(decodedValue, 10, 64)
297			if err != nil || parsed < 0 {
298				return 0, false
299			}
300			gen, found = parsed, true
301		}
302		return gen, found
303	}
