281		if existing, dup := p.reservations[in.RequestID]; dup {
282			if existing.bytes != in.Bytes || existing.tenant != tenant {
283				writeError(w, http.StatusConflict, "idempotency_conflict")
284				return
285			}
286			writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
287			return
288		}
289		// Holding the store lock makes the quota and capacity checks plus the
290		// charge atomic, so concurrent creates can never exceed either limit.
291		if p.tenantQuotaExceeded(tenant, in.Bytes) {
292			writeError(w, http.StatusConflict, "tenant_quota_exceeded")
293			return
294		}
295		allocated := p.allocated()
296		if allocated > p.rawCapacity-in.Bytes {
297			writeError(w, http.StatusConflict, "insufficient_capacity")
298			return
299		}
300		p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes, tenant: tenant}
301		p.tenantUsed[tenant] += in.Bytes
302		s.appendAudit(auditReservationCreated,
303			storagePoolPath+"/"+poolID+"/reservations/"+in.RequestID, poolID, in.Bytes)
304		writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
305	}
306	
307	func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
308		if !validID(poolID) || !validID(requestID) {
309			writeError(w, http.StatusBadRequest, "invalid_request")
310			return
311		}
312		s.mu.Lock()
313		defer s.mu.Unlock()
314		p, ok := s.pools[poolID]
315		if !ok {
316			writeError(w, http.StatusNotFound, "pool_not_found")
317			return
318		}
319		// Deleting an unknown or already-deleted reservation is a success with
320		// no state change, so only a real deletion records an event.
321		if r, existed := p.reservations[requestID]; existed {
322			delete(p.reservations, requestID)
323			p.tenantUsed[r.tenant] -= r.bytes
324			s.appendAudit(auditReservationDeleted,
325				storagePoolPath+"/"+poolID+"/reservations/"+requestID, poolID, -r.bytes)
326		}
327		w.WriteHeader(http.StatusNoContent)
328	}
